@Composable fun HomeScreen(vm:ContentViewModel,role:UserRole,username:String?,go:(String)->Unit){val profile by vm.profile.collectAsState();val courts by vm.courts.collectAsState();val reservations by vm.reservations.collectAsState();val tournaments by vm.tournaments.collectAsState();LaunchedEffect(Unit){vm.loadProfile();vm.loadCourts();vm.loadTournaments();if(role==UserRole.PLAYER)vm.loadReservations()};val name=(profile as? UiState.Success)?.data?.name?.substringBefore(' ')?:username?:if(role==UserRole.PLAYER)"Jugador" else "Manager";LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Hola, $name 👋",style=MaterialTheme.typography.headlineMedium);Text(if(role==UserRole.PLAYER)"¿Dónde quieres jugar hoy?" else "Panel de gestión",color=MaterialTheme.colorScheme.onSurfaceVariant)};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){QuickAction("Canchas",Icons.Default.SportsBasketball,Modifier.weight(1f)){go("courts")};if(role==UserRole.PLAYER)QuickAction("Reservas",Icons.Default.Event,Modifier.weight(1f)){go("reservations")}else QuickAction("Torneos",Icons.Default.EmojiEvents,Modifier.weight(1f)){go("tournaments")}}};if(role==UserRole.PLAYER){val next=(reservations as? UiState.Success)?.data?.filter{it.status==ReservationStatus.CONFIRMED&&runCatching{LocalDateTime.parse(it.startsAt).isAfter(LocalDateTime.now())}.getOrDefault(false)}?.minByOrNull{it.startsAt};next?.let{item{SectionTitle("Próxima reserva","Ver todas"){go("reservations")};ReservationCard(it){go("reservations")}}};val available=(tournaments as?UiState.Success)?.data?.filter{it.status==TournamentStatus.REGISTRATION}?.take(2).orEmpty();if(available.isNotEmpty()){item{SectionTitle("Torneos disponibles","Ver todos"){go("tournaments")}};items(available){TournamentCard(it){go("tournaments")}}}}else{val mineCourts=(courts as?UiState.Success)?.data?.count{it.managerUser==username}?:0;val mineTournaments=(tournaments as?UiState.Success)?.data?.count{it.managerUser==username}?:0;item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(12.dp)){Metric("Canchas",mineCourts,Modifier.weight(1f));Metric("Torneos",mineTournaments,Modifier.weight(1f))}};item{PrimaryButton("Crear cancha",{go("courts")});Spacer(Modifier.height(8.dp));OutlinedButton({go("tournaments")},Modifier.fillMaxWidth()){Text("Crear torneo")}}}}}
