@Composable fun CourtsScreen(vm:ContentViewModel,role:UserRole,username:String?) {
    val state by vm.courts.collectAsState()
    var query by remember { mutableStateOf("") }; var sector by remember { mutableStateOf("") }
    var selected by remember { mutableStateOf<CourtResponse?>(null) }; var create by remember { mutableStateOf(false) }
    var edit by remember { mutableStateOf<CourtResponse?>(null) }; var reserve by remember { mutableStateOf<CourtResponse?>(null) }
    LaunchedEffect(Unit) { vm.loadCourts() }
    Box(Modifier.fillMaxSize()) {
        Column(Modifier.fillMaxSize().padding(horizontal=16.dp)) {
            Text(if(role==UserRole.PLAYER) "Buscar canchas" else "Mis canchas",style=MaterialTheme.typography.headlineMedium,modifier=Modifier.padding(vertical=12.dp))
            OutlinedTextField(query,{query=it},label={Text("Buscar por nombre")},leadingIcon={Icon(Icons.Default.Search,null)},singleLine=true,modifier=Modifier.fillMaxWidth())
            OutlinedTextField(sector,{sector=it},label={Text("Sector")},singleLine=true,modifier=Modifier.fillMaxWidth().padding(top=8.dp))
            StateView(state=state,empty={it.isEmpty()},emptyContent={EmptyState("No encontramos canchas","Prueba cambiando los filtros.",action={query="";sector=""})},onRetry={vm.loadCourts()}) { all ->
                val list=all.filter{c->(role==UserRole.PLAYER||c.managerUser==username)&&c.name.contains(query,true)&&c.sector.contains(sector,true)}
                if(list.isEmpty()) EmptyState("No encontramos canchas","Prueba cambiando los filtros.",action={query="";sector=""})
                else LazyColumn(contentPadding=PaddingValues(bottom=90.dp)){items(list,key={it.id}){c->CourtCard(c,{selected=c},role==UserRole.MANAGER){edit=c}}}
            }
        }
        if(role==UserRole.MANAGER) FloatingActionButton({create=true},Modifier.align(Alignment.BottomEnd).padding(20.dp)){Icon(Icons.Default.Add,"Crear cancha")}
    }
    selected?.let { court -> CourtDetailDialog(court,role,{selected=null},{reserve=court;selected=null}) }
    if(create) CourtFormDialog(null,{create=false}){vm.createCourt(it);create=false}
    edit?.let { court -> CourtEditDialog(court,{edit=null}){request,active->vm.updateCourt(court.id,request,active);edit=null} }
    reserve?.let { court -> ReservationFormDialog(court,{reserve=null}){vm.reserve(it);reserve=null} }
}
@Composable private fun CourtDetailDialog(c:CourtResponse,role:UserRole,close:()->Unit,reserve:(CourtResponse)->Unit){AlertDialog(onDismissRequest=close,title={Text(c.name)},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(10.dp)){StatusChip(if(c.active)"Disponible" else "No disponible",c.active);InfoLine("Sector",c.sector);InfoLine("Deporte",c.sportType.label());InfoLine("Piso",c.floorType);InfoLine("Parqueadero",if(c.hasParking)"Sí" else "No");InfoLine("Precio",money(c.pricePerHour));HorizontalDivider();Text("Disponibilidad",style=MaterialTheme.typography.titleMedium);Text(if(c.active)"Consulta una fecha y hora para reservar." else "Cancha no disponible actualmente")}},confirmButton={if(role==UserRole.PLAYER&&c.active)Button({reserve(c)}){Text("Reservar cancha")}else TextButton(close){Text("Cerrar")}},dismissButton={if(role==UserRole.PLAYER&&c.active)TextButton(close){Text("Volver")}})}
@Composable private fun InfoLine(label:String,value:String){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(label,color=MaterialTheme.colorScheme.onSurfaceVariant);Text(value,style=MaterialTheme.typography.bodyLarge)}}
@Composable private fun CourtFormDialog(existing:CourtResponse?,close:()->Unit,save:(CreateCourtRequest)->Unit){var name by remember{mutableStateOf(existing?.name?:"")};var sector by remember{mutableStateOf(existing?.sector?:"")};var floor by remember{mutableStateOf(existing?.floorType?:"")};var price by remember{mutableStateOf(existing?.pricePerHour?.toString()?:"")};var parking by remember{mutableStateOf(existing?.hasParking?:false)};var error by remember{mutableStateOf<String?>(null)};AlertDialog(onDismissRequest=close,title={Text("Nueva cancha")},text={Column(Modifier.verticalScroll(rememberScrollState())){Field(name,{name=it},"Nombre",error?.takeIf{name.isBlank()});Field(sector,{sector=it},"Sector",error?.takeIf{sector.isBlank()});Field(floor,{floor=it},"Tipo de piso",error?.takeIf{floor.isBlank()});Field(price,{price=it},"Precio por hora",error?.takeIf{price.toDoubleOrNull()?.let{it<=0}!=false});Row(verticalAlignment=Alignment.CenterVertically){Text("Parqueadero",Modifier.weight(1f));Switch(parking,{parking=it})};Text("Deporte: Básquet",color=MaterialTheme.colorScheme.onSurfaceVariant)}},confirmButton={Button({error=Validators.court(name,sector,floor,price.toDoubleOrNull());if(error==null)save(CreateCourtRequest(name.trim(),sector.trim(),parking,SportType.BASKET,floor.trim(),price.toDouble()))}){Text("Crear cancha")}},dismissButton={TextButton(close){Text("Cancelar")}})}
@Composable private fun CourtEditDialog(c:CourtResponse,close:()->Unit,save:(UpdateCourtRequest,Boolean)->Unit){var price by remember{mutableStateOf(c.pricePerHour.toString())};var active by remember{mutableStateOf(c.active)};var error by remember{mutableStateOf<String?>(null)};AlertDialog(onDismissRequest=close,title={Text("Editar cancha")},text={Column{Text(c.name,style=MaterialTheme.typography.titleMedium);Text("El backend solo permite editar precio y estado.",style=MaterialTheme.typography.bodySmall);Field(price,{price=it},"Precio por hora",error);Row(verticalAlignment=Alignment.CenterVertically){Text("Cancha activa",Modifier.weight(1f));Switch(active,{active=it})}}},confirmButton={Button({if(price.toDoubleOrNull()?.let{it>0}!=true)error="El precio debe ser mayor que 0." else save(UpdateCourtRequest(price.toDouble(),active),active)}){Text("Guardar cambios")}},dismissButton={TextButton(close){Text("Cancelar")}})}
