@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun ReservationFormDialog(court:CourtResponse,close:()->Unit,save:(CreateReservationRequest)->Unit) {
    var date by remember { mutableStateOf<LocalDate?>(null) }; var time by remember { mutableStateOf<LocalTime?>(null) }
    var duration by remember { mutableIntStateOf(60) }; var showDate by remember { mutableStateOf(false) }; var showTime by remember { mutableStateOf(false) }
    val starts=if(date!=null&&time!=null) LocalDateTime.of(date,time).withSecond(0).withNano(0) else null
    AlertDialog(onDismissRequest=close,title={Text("Reservar cancha")},text={
        Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(12.dp)){
            Text(court.name,style=MaterialTheme.typography.titleLarge);Text(money(court.pricePerHour),color=MaterialTheme.colorScheme.primary)
            OutlinedButton({showDate=true},Modifier.fillMaxWidth()){Icon(Icons.Default.DateRange,null);Text(" ${date?.format(DateTimeFormatter.ofPattern("d MMM yyyy"))?:"Seleccionar fecha"}")}
            OutlinedButton({showTime=true},Modifier.fillMaxWidth()){Icon(Icons.Default.Schedule,null);Text(" ${time?.format(DateTimeFormatter.ofPattern("HH:mm"))?:"Seleccionar hora"}")}
            Text("Duración"); val durations=listOf(60,90,120)
            SingleChoiceSegmentedButtonRow { durations.forEachIndexed { i,d -> SegmentedButton(selected=duration==d,onClick={duration=d},shape=SegmentedButtonDefaults.itemShape(i,durations.size)){Text("$d min")} } }
            HorizontalDivider();Text("Resumen",style=MaterialTheme.typography.titleMedium);Text("Fecha: ${date?:"Pendiente"}\nHora: ${time?:"Pendiente"}\nDuración: $duration minutos")
        }
    },confirmButton={Button({starts?.let{save(CreateReservationRequest(court.id,it.toString(),duration))}},enabled=starts?.isAfter(LocalDateTime.now())==true){Text("Confirmar reserva")}},dismissButton={TextButton(close){Text("Cancelar")}})
    if(showDate) DatePickerModal({showDate=false}){date=it}; if(showTime) TimePickerModal({showTime=false}){time=it}
}

@OptIn(ExperimentalMaterial3Api::class) @Composable private fun DatePickerModal(close:()->Unit,pick:(LocalDate)->Unit){val state=rememberDatePickerState(initialSelectedDateMillis=System.currentTimeMillis());DatePickerDialog(onDismissRequest=close,confirmButton={Button({state.selectedDateMillis?.let{pick(Instant.ofEpochMilli(it).atZone(ZoneOffset.UTC).toLocalDate())};close()}){Text("Aceptar")}}){DatePicker(state)}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun TimePickerModal(close:()->Unit,pick:(LocalTime)->Unit){val now=LocalTime.now();val state=rememberTimePickerState(now.hour,now.minute,true);AlertDialog(onDismissRequest=close,text={TimePicker(state)},confirmButton={Button({pick(LocalTime.of(state.hour,state.minute));close()}){Text("Aceptar")}},dismissButton={TextButton(close){Text("Cancelar")}})}

@Composable fun TournamentsScreen(vm:ContentViewModel,role:UserRole,username:String?) {
    val state by vm.tournaments.collectAsState(); var filter by remember { mutableStateOf<TournamentStatus?>(null) }
    var selected by remember { mutableStateOf<Long?>(null) }; var create by remember { mutableStateOf(false) }
    LaunchedEffect(Unit){vm.loadTournaments()}
    Box(Modifier.fillMaxSize()) {
        Column(Modifier.fillMaxSize().padding(horizontal=16.dp)) {
            Text(if(role==UserRole.MANAGER)"Mis torneos" else "Torneos",style=MaterialTheme.typography.headlineMedium,modifier=Modifier.padding(vertical=12.dp))
            LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){item{FilterChip(filter==null,{filter=null},{Text("Todos")})};items(TournamentStatus.entries){s->FilterChip(filter==s,{filter=s},{Text(s.label())})}}
            StateView(state=state,empty={it.isEmpty()},emptyContent={EmptyState("No hay torneos","Vuelve pronto para descubrir nuevas competencias.")},onRetry={vm.loadTournaments()}) { all ->
                val list=all.filter{(role==UserRole.PLAYER||it.managerUser==username)&&(filter==null||it.status==filter)}
                if(list.isEmpty()) EmptyState("Sin torneos en esta categoría","Selecciona otro filtro.")
                else LazyColumn(contentPadding=PaddingValues(bottom=90.dp)){items(list,key={it.id}){t->TournamentCard(t){selected=t.id;vm.loadTournament(t.id);vm.loadTeams(t.id)}}}
            }
        }
        if(role==UserRole.MANAGER) FloatingActionButton({create=true},Modifier.align(Alignment.BottomEnd).padding(20.dp)){Icon(Icons.Default.Add,"Crear torneo")}
    }
    selected?.let{id->TournamentDetailDialog(vm,id,role,{selected=null})}
    if(create) TournamentFormDialog({create=false}){vm.createTournament(it);create=false}
}
@Composable private fun TournamentDetailDialog(vm:ContentViewModel,id:Long,role:UserRole,close:()->Unit) {
    val state by vm.tournamentDetail.collectAsState(); val teams by vm.teams.collectAsState()
    var tab by remember { mutableIntStateOf(0) }; var register by remember { mutableStateOf(false) }
    var teamDetail by remember { mutableStateOf<TeamResponse?>(null) }; var manage by remember { mutableStateOf<MatchResponse?>(null) }; var confirmStart by remember { mutableStateOf(false) }
    AlertDialog(onDismissRequest=close,title={Text((state as?UiState.Success)?.data?.tournament?.name?:"Torneo")},text={
        StateView(state=state,onRetry={vm.loadTournament(id)}) { progress ->
            val tournament=progress.tournament
            Column(Modifier.heightIn(max=590.dp)) {
                Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){StatusChip(tournament.status.label());Text("${tournament.registeredTeams}/${tournament.maxTeams} equipos")}
                tournament.prize?.let{Text("Premio: $it")};tournament.courtName?.let{Text("Cancha: $it")}
                if(tournament.status==TournamentStatus.FINISHED&&tournament.championTeamName!=null) Card(Modifier.fillMaxWidth().padding(vertical=10.dp),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.secondaryContainer)){Column(Modifier.fillMaxWidth().padding(16.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("🏆 CAMPEÓN");Text(tournament.championTeamName,style=MaterialTheme.typography.headlineSmall)}}
                TabRow(tab){listOf("Resumen","Equipos","Cuadro").forEachIndexed{i,label->Tab(tab==i,{tab=i},text={Text(label)})}}
                when(tab) {
                    0 -> Column(Modifier.padding(top=12.dp)) {
                        InfoLine("Deporte",tournament.sportType.label());InfoLine("Estado",tournament.status.label())
                        if(role==UserRole.PLAYER&&tournament.status==TournamentStatus.REGISTRATION) PrimaryButton("Inscribir equipo",{register=true},modifier=Modifier.padding(top=12.dp))
                        if(role==UserRole.MANAGER&&tournament.status==TournamentStatus.REGISTRATION){val ready=tournament.registeredTeams==tournament.maxTeams;Text(if(ready)"El torneo está listo para iniciar." else "Faltan ${tournament.maxTeams-tournament.registeredTeams} equipos para iniciar.",Modifier.padding(top=12.dp));PrimaryButton("Iniciar torneo",{confirmStart=true},ready,Modifier.padding(top=8.dp))}
                    }
                    1 -> StateView(state=teams,empty={it.isEmpty()},emptyContent={EmptyState("Sin equipos","Aún no hay equipos inscritos.")}) { list -> LazyColumn { items(list){team->TeamCard(team){teamDetail=team}} } }
                    else -> LazyColumn { progress.rounds.forEach { round -> item { Text(round.roundName,style=MaterialTheme.typography.titleLarge,modifier=Modifier.padding(top=12.dp)) }; items(round.matches.sortedBy{it.positionInRound}) { match -> MatchCard(match,round.roundName,if(role==UserRole.MANAGER&&match.status!=MatchStatus.PLAYED){{manage=match}}else null) } } }
                }
            }
        }
    },confirmButton={TextButton(close){Text("Cerrar")}})
    if(register) TeamFormDialog({register=false}){vm.registerTeam(id,it);register=false;vm.loadTeams(id);vm.loadTournament(id)}
    teamDetail?.let{team->TeamDetailDialog(team){teamDetail=null}}
    if(confirmStart) ConfirmDialog("¿Iniciar torneo?","Se generará el cuadro y ya no se admitirán equipos.","Iniciar",{confirmStart=false}){vm.startTournament(id);vm.loadTournament(id);confirmStart=false}
    manage?.let { match -> MatchManageDialog(match,{manage=null}) { date,home,away -> if(date!=null)vm.scheduleMatch(id,match.id,date) else vm.scoreMatch(id,match.id,home!!,away!!);manage=null } }
}
@Composable private fun TeamDetailDialog(t:TeamResponse,close:()->Unit){AlertDialog(onDismissRequest=close,title={Text(t.name)},text={Column(verticalArrangement=Arrangement.spacedBy(7.dp)){StatusChip(if(t.stats.eliminated)"Eliminado" else "En competencia",!t.stats.eliminated);Text("Contacto",style=MaterialTheme.typography.titleMedium);Text(t.contactName);Text(t.contactEmail);Text(t.contactPhone);HorizontalDivider();Text("Estadísticas",style=MaterialTheme.typography.titleMedium);InfoLine("Partidos jugados",t.stats.matchesPlayed.toString());InfoLine("Victorias",t.stats.matchesWon.toString());InfoLine("Derrotas",t.stats.matchesLost.toString());InfoLine("Puntos a favor",t.stats.pointsFor.toString());InfoLine("Puntos en contra",t.stats.pointsAgainst.toString())}},confirmButton={TextButton(close){Text("Cerrar")}})}
@Composable private fun TeamFormDialog(close:()->Unit,save:(RegisterTeamRequest)->Unit){var n by remember{mutableStateOf("")};var c by remember{mutableStateOf("")};var e by remember{mutableStateOf("")};var p by remember{mutableStateOf("")};var error by remember{mutableStateOf<String?>(null)};AlertDialog(onDismissRequest=close,title={Text("Inscribir equipo")},text={Column(Modifier.verticalScroll(rememberScrollState())){Field(n,{n=it},"Nombre del equipo",error?.takeIf{n.isBlank()});Field(c,{c=it},"Responsable",error?.takeIf{c.isBlank()});Field(e,{e=it},"Correo",error?.takeIf{e.isBlank()});Field(p,{p=it},"Teléfono",error?.takeIf{p.isBlank()})}},confirmButton={Button({error=Validators.team(n,c,e,p);if(error==null)save(RegisterTeamRequest(n,c,e,p))}){Text("Inscribir equipo")}},dismissButton={TextButton(close){Text("Cancelar")}})}
@Composable private fun TournamentFormDialog(close:()->Unit,save:(CreateTournamentRequest)->Unit){var n by remember{mutableStateOf("")};var teams by remember{mutableStateOf("4")};var prize by remember{mutableStateOf("")};var error by remember{mutableStateOf<String?>(null)};AlertDialog(onDismissRequest=close,title={Text("Crear torneo")},text={Column{Field(n,{n=it},"Nombre",error?.takeIf{n.isBlank()});Field(teams,{teams=it},"Máximo de equipos",error?.takeIf{teams.toIntOrNull()==null});Field(prize,{prize=it},"Premio (opcional)");Text("Deporte: Básquet")}},confirmButton={Button({error=Validators.tournament(n,teams.toIntOrNull());if(error==null)save(CreateTournamentRequest(n,SportType.BASKET,teams.toInt(),prize.ifBlank{null}))}){Text("Crear torneo")}},dismissButton={TextButton(close){Text("Cancelar")}})}
@Composable private fun MatchManageDialog(m:MatchResponse,close:()->Unit,save:(String?,Int?,Int?)->Unit){if(m.status==MatchStatus.PENDING){var date by remember{mutableStateOf<LocalDate?>(null)};var time by remember{mutableStateOf<LocalTime?>(null)};var sd by remember{mutableStateOf(false)};var st by remember{mutableStateOf(false)};AlertDialog(onDismissRequest=close,title={Text("Programar partido")},text={Column(horizontalAlignment=Alignment.CenterHorizontally){Text("${m.homeTeamName?:"Por definir"} vs ${m.awayTeamName?:"Por definir"}");OutlinedButton({sd=true},Modifier.fillMaxWidth()){Text(date?.toString()?:"Seleccionar fecha")};OutlinedButton({st=true},Modifier.fillMaxWidth()){Text(time?.toString()?:"Seleccionar hora")}}},confirmButton={Button({if(date!=null&&time!=null)save(LocalDateTime.of(date,time).toString(),null,null)},enabled=date!=null&&time!=null){Text("Programar")}},dismissButton={TextButton(close){Text("Cancelar")}});if(sd)DatePickerModal({sd=false}){date=it};if(st)TimePickerModal({st=false}){time=it}}else ScoreDialog(m,close,save)}
@Composable private fun ScoreDialog(m:MatchResponse,close:()->Unit,save:(String?,Int?,Int?)->Unit){var h by remember{mutableStateOf("")};var a by remember{mutableStateOf("")};var error by remember{mutableStateOf<String?>(null)};var confirm by remember{mutableStateOf(false)};AlertDialog(onDismissRequest=close,title={Text("Registrar resultado")},text={Column{Field(h,{h=it},m.homeTeamName?:"Local",error);Field(a,{a=it},m.awayTeamName?:"Visitante",error)}},confirmButton={Button({error=Validators.score(h.toIntOrNull(),a.toIntOrNull());if(error==null)confirm=true}){Text("Guardar resultado")}},dismissButton={TextButton(close){Text("Cancelar")}});if(confirm)ConfirmDialog("Confirmar marcador","${m.homeTeamName}: $h\n${m.awayTeamName}: $a","Guardar",{confirm=false}){save(null,h.toInt(),a.toInt());confirm=false}} 

@Composable fun ProfileScreen(vm:ContentViewModel,role:UserRole,onLogout:()->Unit){val state by vm.profile.collectAsState();var edit by remember{mutableStateOf(false)};var logout by remember{mutableStateOf(false)};LaunchedEffect(Unit){vm.loadProfile()};StateView(state,onRetry={vm.loadProfile()}){p->Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Surface(shape=MaterialTheme.shapes.large,color=MaterialTheme.colorScheme.primaryContainer){Icon(Icons.Default.Person,null,Modifier.padding(24.dp).size(60.dp),tint=MaterialTheme.colorScheme.primary)};Text(p.name,style=MaterialTheme.typography.headlineMedium,modifier=Modifier.padding(top=14.dp));StatusChip(role.name);Card(Modifier.fillMaxWidth().padding(vertical=20.dp)){Column(Modifier.padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){InfoLine("Correo",p.email?:"Sin correo");InfoLine("Teléfono",p.phone?:"Sin teléfono")}};PrimaryButton("Editar perfil",{edit=true});OutlinedButton({logout=true},Modifier.fillMaxWidth().padding(top=10.dp)){Icon(Icons.Default.Logout,null);Text(" Cerrar sesión")};if(edit)ProfileFormDialog(p,{edit=false}){vm.saveProfile(it,false);edit=false}}};if(logout)ConfirmDialog("¿Cerrar sesión?","Tendrás que volver a ingresar tus credenciales.","Cerrar sesión",{logout=false}){onLogout();logout=false}}
@Composable private fun ProfileFormDialog(p:UserResponse,close:()->Unit,save:(UserRequest)->Unit){var n by remember{mutableStateOf(p.name)};var e by remember{mutableStateOf(p.email?:"")};var ph by remember{mutableStateOf(p.phone?:"")};var error by remember{mutableStateOf<String?>(null)};AlertDialog(onDismissRequest=close,title={Text("Editar perfil")},text={Column{Field(n,{n=it},"Nombre",error?.takeIf{n.isBlank()});Field(e,{e=it},"Correo",error?.takeIf{e.isNotBlank()&&!e.contains('@')});Field(ph,{ph=it},"Teléfono",error?.takeIf{ph.isNotBlank()&&ph.length<7})}},confirmButton={Button({error=Validators.profile(n,e,ph);if(error==null)save(UserRequest(n,e.ifBlank{null},ph.ifBlank{null}))}){Text("Guardar cambios")}},dismissButton={TextButton(close){Text("Cancelar")}})}
